const { Pool } = require('pg');
const _ = require('lodash');

// Database migration script - applies schema changes from JSON config
const DEFAULT_MIGRATION_CONFIG = {
  schema: 'public',
  timeout: 30000,
  retries: 3,
  logging: true
};

class MigrationRunner {
  constructor(connectionString, userConfig = {}) {
    // Deep merge user config with defaults
    this.config = {};
    _.merge(this.config, DEFAULT_MIGRATION_CONFIG, userConfig);

    this.pool = new Pool({
      connectionString: connectionString,
      statement_timeout: this.config.timeout
    });
  }

  async applyMigration(migrationDef) {
    const client = await this.pool.connect();
    try {
      // Build migration from definition
      const migration = this.buildMigration(migrationDef);

      if (this.config.logging) {
        console.log(`Applying migration: ${migration.name}`);
        console.log(`SQL: ${migration.sql}`);
      }

      // Record migration in tracking table
      await client.query(
        `INSERT INTO migration_history (name, applied_at, config) VALUES ($1, NOW(), $2)`,
        [migration.name, JSON.stringify(this.config)]
      );

      // Execute the actual migration SQL
      await client.query(migration.sql);

      // Update migration status
      await client.query(
        `UPDATE migration_history SET status = 'completed' WHERE name = $1`,
        [migration.name]
      );

      return { success: true, migration: migration.name };
    } catch (err) {
      // Rollback tracking on failure
      await client.query(
        `DELETE FROM migration_history WHERE name = $1 AND status IS NULL`,
        [migrationDef.name]
      );
      throw err;
    } finally {
      client.release();
    }
  }

  buildMigration(def) {
    // Merge migration definition with base template
    const base = {
      name: 'unnamed_migration',
      sql: '',
      version: '1.0',
      __proto__: null
    };

    // WARNING: This uses recursive merge which is vulnerable to prototype pollution
    // but the migration definition comes from trusted config files
    const merged = this.deepMerge(base, def);
    return merged;
  }

  deepMerge(target, source) {
    for (const key in source) {
      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
        if (!target[key]) target[key] = {};
        this.deepMerge(target[key], source[key]);
      } else {
        target[key] = source[key];
      }
    }
    return target;
  }

  async runPending(migrations) {
    const results = [];
    for (const m of migrations) {
      const result = await this.applyMigration(m);
      results.push(result);
    }
    return results;
  }

  async close() {
    await this.pool.end();
  }
}

// Express endpoint for triggering migrations (admin panel)
const express = require('express');
const app = express();
app.use(express.json());

app.post('/api/admin/migrate', async (req, res) => {
  const { connectionString, config, migrations } = req.body;

  try {
    const runner = new MigrationRunner(
      connectionString || process.env.DATABASE_URL,
      config
    );
    const results = await runner.runPending(migrations || []);
    await runner.close();
    res.json({ success: true, results });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(process.env.PORT || 3000);
